/**
 * NexoWatt unattended-upgrade quarantine.
 * This release never enables automatic code installation. A repository label,
 * adapter prefix or free-form publisher field cannot authenticate a release.
 * Existing EOS-managed policies are migrated to none; manual administrator
 * updates remain available. A future signed, version-pinned rollout is separate.
 */

export type NexoWattAutoUpdatePolicy = 'none' | 'patch' | 'minor' | 'major';

interface AdapterObjectLike {
    _id?: string;
    common?: Record<string, any>;
    native?: Record<string, any>;
}

interface NexoWattAutoUpdateAdapter {
    namespace: string;
    host?: string;
    log: {
        debug: (message: string) => void;
        info: (message: string) => void;
        warn: (message: string) => void;
        error: (message: string) => void;
    };
    getForeignObjectAsync: (id: string) => Promise<any>;
    setForeignObjectAsync: (id: string, object: any, options?: any) => Promise<any>;
    getObjectViewAsync: (design: string, search: string, params: any, options?: any) => Promise<any>;
    getStateAsync: (id: string) => Promise<any>;
    setStateAsync: (id: string, value: any, ack?: boolean) => Promise<any>;
    sendToHostAsync?: (host: string, command: string, message: any) => Promise<any>;
}

export interface NexoWattStableUpdateStatus {
    enabled: boolean;
    repository: string;
    managedAdapters: string[];
    availableStableAdapters: string[];
    lastSync: number;
    lastRepositoryRefresh: number;
    error: string;
    policy: 'none';
    blocked: true;
    source: 'ioBroker-native-auto-upgrade';
}

interface PersistedState {
    previousPolicies?: Record<string, NexoWattAutoUpdatePolicy | null>;
    previousRepositoryEnabled?: boolean | null;
    previousActiveRepo?: string[];
    selectedRepository?: string;
    ownsActiveRepoOrder?: boolean;
    managedAdapters?: string[];
    availableStableAdapters?: string[];
    lastSync?: number;
    lastRepositoryRefresh?: number;
    error?: string;
}

const ADMIN_USER = 'system.user.admin';
const POLICY = 'none' as const;
const BLOCK_REASON = 'UNATTENDED_UPDATES_BLOCKED_UNVERIFIED_RELEASE';
const RECONCILE_INTERVAL_MS = 6 * 60 * 60 * 1000;
const ENABLED_STATE_ID = 'info.nexowattStableUpdatesEnabled';
const STATUS_STATE_ID = 'info.nexowattStableUpdatesState';

const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value));
const normalizedName = (value: unknown): string => String(value || '').trim().replace(/^system\.adapter\./, '').replace(/\.\d+$/, '');
const validAdapterName = (name: string): boolean => /^[a-z][a-z0-9-]{0,63}$/.test(name);

// Classification for quarantine ONLY. This is deliberately never an issuer or
// package trust decision; textual metadata provides no evidence of provenance.
export function isNexoWattRepositoryEntry(name: string, _entry?: any): boolean {
    const adapterName = normalizedName(name).toLowerCase();
    return validAdapterName(adapterName) && (adapterName === 'eos-admin'
        || adapterName.startsWith('nexowatt-') || adapterName.startsWith('eos-'));
}

export class NexoWattStableUpdateManager {
    private timer?: NodeJS.Timeout;
    private reconcilePromise?: Promise<NexoWattStableUpdateStatus>;
    private retryTimer?: NodeJS.Timeout;
    private stopped = false;
    private cachedState: PersistedState = {};

    constructor(private readonly adapter: NexoWattAutoUpdateAdapter) {}

    private get instanceId(): string { return `system.adapter.${this.adapter.namespace}`; }

    async start(): Promise<NexoWattStableUpdateStatus> {
        this.stopped = false;
        // Do not leave a legacy auto-install window while browser assets load.
        const status = await this.reconcile('startup-security-migration');
        this.ensurePeriodicTimer();
        return status;
    }

    stop(): void {
        this.stopped = true;
        if (this.timer) clearInterval(this.timer);
        if (this.retryTimer) clearTimeout(this.retryTimer);
        this.timer = undefined;
        this.retryTimer = undefined;
    }

    async getStatus(refresh = false): Promise<NexoWattStableUpdateStatus> {
        if (refresh) return this.reconcile('status');
        const persisted = await this.readPersisted();
        return this.statusFromPersisted(persisted.enabled, persisted.state);
    }

    async setEnabled(_enabled: boolean): Promise<NexoWattStableUpdateStatus> {
        if (this.stopped) return this.statusFromPersisted(false, this.cachedState);
        // The former UI/API switch is not an override for release integrity.
        const status = await this.reconcile('settings-security-quarantine');
        this.ensurePeriodicTimer();
        return status;
    }

    async reconcile(reason = 'manual'): Promise<NexoWattStableUpdateStatus> {
        if (this.reconcilePromise) return this.reconcilePromise;
        this.reconcilePromise = this.reconcileInternal(reason).finally(() => { this.reconcilePromise = undefined; });
        return this.reconcilePromise;
    }

    private ensurePeriodicTimer(): void {
        if (this.timer || this.stopped) return;
        this.timer = setInterval(() => {
            if (!this.stopped) void this.reconcile('interval').catch(() => this.adapter.log.warn('[NexoWatt stable updates] UNATTENDED_UPDATE_MIGRATION_FAILED'));
        }, RECONCILE_INTERVAL_MS);
        this.timer.unref?.();
    }

    private parseState(value: unknown): PersistedState | null {
        if (value && typeof value === 'object' && !Array.isArray(value)) return clone(value as PersistedState);
        if (typeof value !== 'string' || !value.trim()) return null;
        try {
            const parsed = JSON.parse(value);
            return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed as PersistedState : null;
        } catch {
            return null;
        }
    }

    private async readPersisted(): Promise<{ enabled: boolean; state: PersistedState }> {
        // Legacy 7.10.1 values are read once as a migration fallback. They are
        // never written back to the instance native object.
        let legacyNative: Record<string, any> = {};
        try {
            const instance = await this.adapter.getForeignObjectAsync(this.instanceId);
            legacyNative = instance?.native || {};
        } catch (error) {
            this.adapter.log.debug(`[NexoWatt stable updates] Cannot read legacy native state: ${error instanceof Error ? error.message : error}`);
        }

        const enabled = false;
        let state = Object.keys(this.cachedState).length
            ? clone(this.cachedState)
            : clone((legacyNative.eosNexoWattAutoUpdateState || {}) as PersistedState);

        try {
            const enabledState = await this.adapter.getStateAsync(ENABLED_STATE_ID);
            // Read legacy state for migration availability, never for permission.
            if (enabledState?.val === true) this.adapter.log.debug('[NexoWatt stable updates] Legacy enable flag ignored by security quarantine');
        } catch (error) {
            this.adapter.log.debug(`[NexoWatt stable updates] Cannot read enabled state: ${error instanceof Error ? error.message : error}`);
        }

        try {
            const persistedState = await this.adapter.getStateAsync(STATUS_STATE_ID);
            const parsed = this.parseState(persistedState?.val);
            if (parsed) state = parsed;
        } catch (error) {
            this.adapter.log.debug(`[NexoWatt stable updates] Cannot read status state: ${error instanceof Error ? error.message : error}`);
        }

        this.cachedState = clone(state);
        return { enabled, state };
    }

    private statusFromPersisted(_enabled: boolean, state: PersistedState): NexoWattStableUpdateStatus {
        return {
            enabled: false,
            blocked: true,
            repository: String(state.selectedRepository || ''),
            managedAdapters: Array.isArray(state.managedAdapters) ? state.managedAdapters.map(String).sort() : [],
            availableStableAdapters: Array.isArray(state.availableStableAdapters) ? state.availableStableAdapters.map(String).sort() : [],
            lastSync: Number(state.lastSync || 0),
            lastRepositoryRefresh: Number(state.lastRepositoryRefresh || 0),
            error: String(state.error || BLOCK_REASON),
            policy: POLICY,
            source: 'ioBroker-native-auto-upgrade',
        };
    }

    private async reconcileInternal(reason: string): Promise<NexoWattStableUpdateStatus> {
        const persisted = await this.readPersisted();
        const { enabled } = persisted;
        const state = clone(persisted.state);
        if (this.stopped) return this.statusFromPersisted(enabled, state);
        try {
            return await this.disable(state, reason);
        } catch (error) {
            const message = 'UNATTENDED_UPDATE_MIGRATION_FAILED';
            state.error = message;
            state.lastSync = Date.now();
            if (!this.stopped) await this.persist(enabled, state);
            if (!this.stopped) this.scheduleRetry();
            if (!this.stopped) this.adapter.log.warn(`[NexoWatt stable updates] ${message}`);
            return this.statusFromPersisted(enabled, state);
        }
    }

    private async readInstalledAdapters(): Promise<Map<string, AdapterObjectLike>> {
        const view = await this.adapter.getObjectViewAsync('system', 'adapter', {
            startkey: 'system.adapter.',
            endkey: 'system.adapter.\u9999',
        }, { user: ADMIN_USER });
        const result = new Map<string, AdapterObjectLike>();
        for (const row of view?.rows || []) {
            const object = row?.value || row?.doc;
            const name = normalizedName(object?.common?.name || row?.id || object?._id);
            if (name && object?.common?.version) result.set(name, object);
        }
        return result;
    }

    private async disable(state: PersistedState, reason: string): Promise<NexoWattStableUpdateStatus> {
        const installed = await this.readInstalledAdapters();
        const names = new Set([
            ...[...installed.keys()].filter(name => isNexoWattRepositoryEntry(name)),
            ...Object.keys(state.previousPolicies || {}).filter(validAdapterName),
            ...(Array.isArray(state.managedAdapters) ? state.managedAdapters.filter(name => typeof name === 'string' && validAdapterName(name)) : []),
        ]);
        state.previousPolicies ||= {};
        for (const name of [...names].sort()) {
            if (this.stopped) return this.statusFromPersisted(false, state);
            const current = await this.adapter.getForeignObjectAsync(`system.adapter.${name}`);
            if (!current?.common) continue;
            // Preserve the old value only for an explicitly reviewed later
            // migration. Never restore an automatic policy in this release.
            if (!Object.prototype.hasOwnProperty.call(state.previousPolicies, name)) {
                const previous = current.common.automaticUpgrade;
                state.previousPolicies[name] = ['none', 'patch', 'minor', 'major'].includes(previous) ? previous : null;
            }
            await this.writeAdapterPolicy(name, POLICY);
        }
        const systemConfig = await this.adapter.getForeignObjectAsync('system.config');
        if (systemConfig?.common) {
            let systemConfigChanged = false;
            const auto = systemConfig.common.adapterAutoUpgrade && typeof systemConfig.common.adapterAutoUpgrade === 'object'
                ? clone(systemConfig.common.adapterAutoUpgrade)
                : null;
            if (auto && state.selectedRepository) {
                auto.repositories = auto.repositories && typeof auto.repositories === 'object' ? { ...auto.repositories } : {};
                if (auto.repositories[state.selectedRepository] === true && (state.previousRepositoryEnabled === false || state.previousRepositoryEnabled === null)) {
                    if (state.previousRepositoryEnabled === null || state.previousRepositoryEnabled === undefined) {
                        delete auto.repositories[state.selectedRepository];
                    } else {
                        auto.repositories[state.selectedRepository] = state.previousRepositoryEnabled;
                    }
                    systemConfigChanged = true;
                }
                if (JSON.stringify(systemConfig.common.adapterAutoUpgrade) !== JSON.stringify(auto)) {
                    systemConfig.common.adapterAutoUpgrade = auto;
                    systemConfigChanged = true;
                }
            }
            if (state.ownsActiveRepoOrder && Array.isArray(state.previousActiveRepo)
                && Array.isArray(systemConfig.common.activeRepo)
                && systemConfig.common.activeRepo[0] === state.selectedRepository) {
                systemConfig.common.activeRepo = [...state.previousActiveRepo];
                systemConfigChanged = true;
            }
            if (systemConfigChanged && !this.stopped) {
                await this.adapter.setForeignObjectAsync('system.config', systemConfig, { user: ADMIN_USER });
            }
        }
        state.previousRepositoryEnabled = undefined;
        state.previousActiveRepo = undefined;
        state.ownsActiveRepoOrder = false;
        state.managedAdapters = [...names].sort();
        state.availableStableAdapters = [];
        state.lastSync = Date.now();
        state.error = BLOCK_REASON;
        if (!this.stopped) await this.persist(false, state);
        if (!this.stopped) this.adapter.log.info(`[NexoWatt stable updates] Unattended installation blocked; managed policies quarantined (${reason})`);
        return this.statusFromPersisted(false, state);
    }

    private async writeAdapterPolicy(name: string, policy: NexoWattAutoUpdatePolicy | null): Promise<void> {
        if (!validAdapterName(name)) throw new Error('invalidManagedAdapterName');
        const id = `system.adapter.${name}`;
        const object = await this.adapter.getForeignObjectAsync(id);
        if (!object?.common || this.stopped) return;
        const current = object.common.automaticUpgrade as NexoWattAutoUpdatePolicy | undefined;
        if ((policy === null && current === undefined) || current === policy) return;
        if (policy === null) delete object.common.automaticUpgrade;
        else object.common.automaticUpgrade = policy;
        await this.adapter.setForeignObjectAsync(id, object, { user: ADMIN_USER });
    }

    private async persist(enabled: boolean, state: PersistedState): Promise<void> {
        if (this.stopped) return;
        this.cachedState = clone(state);

        const currentEnabled = await this.adapter.getStateAsync(ENABLED_STATE_ID).catch(() => null);
        if (currentEnabled?.val !== enabled) {
            await this.adapter.setStateAsync(ENABLED_STATE_ID, enabled, true);
        }

        const serialized = JSON.stringify(state);
        const currentState = await this.adapter.getStateAsync(STATUS_STATE_ID).catch(() => null);
        const currentSerialized = typeof currentState?.val === 'string'
            ? currentState.val
            : currentState?.val == null ? '' : JSON.stringify(currentState.val);
        if (currentSerialized !== serialized) {
            await this.adapter.setStateAsync(STATUS_STATE_ID, serialized, true);
        }
    }

    private scheduleRetry(): void {
        if (this.retryTimer) clearTimeout(this.retryTimer);
        this.retryTimer = setTimeout(() => {
            this.retryTimer = undefined;
            if (!this.stopped) void this.reconcile('retry').catch(() => this.adapter.log.warn('[NexoWatt stable updates] UNATTENDED_UPDATE_MIGRATION_FAILED'));
        }, 60_000);
        this.retryTimer.unref?.();
    }

}

'use strict';

// ioBroker's file API returns complete buffers. Metadata admission and the
// post-read limit below do not make its underlying allocation a bounded stream.
// Directory exports are deliberately disabled until a bounded streaming API is used.
const MAX_BYTES = 16 * 1024 * 1024;
const MAX_ENTRIES = 1000;
const MAX_CONCURRENT = 2;
const DEADLINE_MS = 5000;
let active = 0;
const userPattern = /^system\.user\.[a-z0-9_.@-]{1,128}$/i;
const namespacePattern = /^[a-z0-9][a-z0-9_.-]{0,127}$/i;

function failure(code, status) { return Object.assign(new Error(code), { code, status }); }

function parseDbFileRequest(input) {
    if (typeof input !== 'string' || input.length > 4096 || !input.startsWith('/')) throw failure('FILE_PATH_INVALID', 400);
    const rawPath = input.split('?')[0];
    // Reject separators hidden from the router, fragments, double encoding and
    // platform-specific path delimiters. Queries are never part of a filename.
    if (/%(?:2f|5c|3f|23|25|00)/i.test(rawPath) || /[\\#\u0000-\u001f\u007f]/.test(rawPath)) throw failure('FILE_PATH_INVALID', 400);
    let pathname;
    try { pathname = decodeURIComponent(rawPath); } catch { throw failure('FILE_PATH_INVALID', 400); }
    if (/[\\?#%:\u0000-\u001f\u007f]/.test(pathname)) throw failure('FILE_PATH_INVALID', 400);
    const parts = pathname.slice(1).split('/');
    const namespace = parts.shift();
    if (!namespacePattern.test(namespace || '') || namespace.includes('..')) throw failure('FILE_PATH_INVALID', 400);
    if (parts.length > 16 || parts.some(part => part === '.' || part === '..' || part.length > 255)) throw failure('FILE_PATH_INVALID', 400);
    if (parts.length && parts.at(-1) === '') parts.pop();
    if (parts.some(part => !part)) throw failure('FILE_PATH_INVALID', 400);
    return { namespace, filePath: parts.join('/') || 'index.html' };
}

function responseAvailable(req, res) { return !req.aborted && !res.destroyed && !res.writableEnded; }
function sendError(req, res, code, status) {
    if (responseAvailable(req, res) && !res.headersSent) res.status(status).json({ error: code });
}

function responseType(filePath) {
    const extension = filePath.split('.').at(-1).toLowerCase();
    const raster = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', avif: 'image/avif', ico: 'image/x-icon', bmp: 'image/bmp' };
    if (Object.hasOwn(raster, extension)) return { type: raster[extension], attachment: false };
    if (['txt', 'log', 'csv', 'json'].includes(extension)) return { type: 'text/plain; charset=utf-8', attachment: false };
    // Never render untrusted HTML, SVG, JavaScript, XML or PDF on the Admin origin.
    return { type: 'application/octet-stream', attachment: true };
}

async function serveDbFile({ adapter, req, res, namespace, filePath, user }) {
    for (const [header, value] of Object.entries({ 'Cache-Control': 'no-store', Pragma: 'no-cache', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer', 'Content-Security-Policy': "sandbox; default-src 'none'; base-uri 'none'; frame-ancestors 'none'" })) res.setHeader(header, value);
    if (typeof user !== 'string' || !userPattern.test(user)) { sendError(req, res, 'FILE_AUTH_REQUIRED', 403); return; }
    // Validate even when the caller accidentally bypasses the URL parser.
    try {
        const checked = parseDbFileRequest(`/${namespace}/${filePath}`);
        if (checked.namespace !== namespace || checked.filePath !== filePath) throw failure('FILE_PATH_INVALID', 400);
    } catch { sendError(req, res, 'FILE_PATH_INVALID', 400); return; }
    if (!responseAvailable(req, res)) return;
    if (active >= MAX_CONCURRENT) { sendError(req, res, 'FILE_CAPACITY_UNAVAILABLE', 503); return; }
    active++;
    let stopped = false;
    let timer;
    let resolveRequest;
    const returned = new Promise(resolve => { resolveRequest = resolve; });
    const cleanup = () => {
        clearTimeout(timer);
        req.removeListener?.('aborted', abort);
        res.removeListener?.('close', close);
    };
    const stop = (code, status) => {
        if (stopped) return;
        stopped = true;
        cleanup();
        if (res.headersSent && !res.writableFinished) res.destroy?.();
        else if (code) sendError(req, res, code, status);
        resolveRequest();
    };
    const abort = () => stop(null, 0);
    const close = () => { if (!res.writableFinished) abort(); };
    req.once?.('aborted', abort);
    res.once?.('close', close);
    timer = setTimeout(() => stop('FILE_DEADLINE_EXCEEDED', 504), DEADLINE_MS);
    const assertLive = () => { if (stopped || !responseAvailable(req, res)) throw failure('FILE_ABORTED', 499); };
    // There is no pending queue. A timed-out, non-cancellable DB call keeps its
    // reservation until it settles, so repeated timeouts cannot spawn more work.
    void (async () => {
        try {
            const split = filePath.lastIndexOf('/');
            const parent = split < 0 ? '' : filePath.slice(0, split);
            const leaf = filePath.slice(split + 1);
            const options = { user };
            const entries = await adapter.readDirAsync(namespace, parent, options);
            assertLive();
            if (!Array.isArray(entries) || entries.length > MAX_ENTRIES) throw failure('FILE_DIRECTORY_LIMIT', 413);
            const matches = entries.filter(entry => entry && entry.file === leaf);
            if (matches.length !== 1) throw failure('FILE_NOT_FOUND', 404);
            const metadata = matches[0];
            if (metadata.isDir) throw failure('DIRECTORY_EXPORT_DISABLED', 403);
            const size = metadata.stats?.size;
            if (!Number.isSafeInteger(size) || size < 0) throw failure('FILE_METADATA_UNAVAILABLE', 503);
            if (size > MAX_BYTES) throw failure('FILE_SIZE_LIMIT', 413);
            const result = await adapter.readFileAsync(namespace, filePath, options);
            assertLive();
            const file = result?.file;
            const length = Buffer.isBuffer(file) ? file.length : typeof file === 'string' ? Buffer.byteLength(file, 'utf8') : -1;
            if (length < 0) throw failure('FILE_READ_UNAVAILABLE', 503);
            if (length > MAX_BYTES) throw failure('FILE_SIZE_LIMIT', 413);
            const output = responseType(filePath);
            res.setHeader('Content-Type', output.type);
            if (output.attachment) {
                const encoded = encodeURIComponent(leaf).replace(/[!'()*]/g, c => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
                res.setHeader('Content-Disposition', `attachment; filename="download"; filename*=UTF-8''${encoded}`);
            }
            // No automatic unlink: a GET must not delete a controller file.
            await new Promise((resolve, reject) => {
                const removeOutputListeners = () => {
                    res.removeListener?.('finish', finished);
                    res.removeListener?.('close', finished);
                };
                const finished = () => {
                    removeOutputListeners();
                    resolve();
                };
                res.once?.('finish', finished);
                res.once?.('close', finished);
                try {
                    res.status(200).send(file);
                    if (res.writableFinished || res.destroyed || typeof res.once !== 'function') finished();
                } catch (error) {
                    removeOutputListeners();
                    reject(error);
                }
            });
        } catch (error) {
            if (!stopped && error?.code !== 'FILE_ABORTED') {
                const safe = ['FILE_DIRECTORY_LIMIT', 'FILE_NOT_FOUND', 'DIRECTORY_EXPORT_DISABLED', 'FILE_METADATA_UNAVAILABLE', 'FILE_SIZE_LIMIT', 'FILE_READ_UNAVAILABLE'].includes(error?.code);
                sendError(req, res, safe ? error.code : 'FILE_READ_UNAVAILABLE', safe ? error.status : 403);
            }
        } finally {
            active--;
            stopped = true;
            cleanup();
            resolveRequest();
        }
    })();
    return returned;
}

module.exports = { parseDbFileRequest, serveDbFile };

'use strict';
const https = require('node:https');
const { performance } = require('node:perf_hooks');

/** External JSON GET with one total budget, including DNS, TLS and body. No redirects/retries. */
function requestHttpsJson(input, options = {}) {
    const started = performance.now();
    return new Promise((resolve, reject) => {
        let request;
        let response;
        let settled = false;
        let timer;
        const budget = Math.min(5000, options.budgetMs === undefined ? 5000 : options.budgetMs);
        const maximum = options.maxBytes === undefined ? 1024 * 1024 : options.maxBytes;
        const finish = (error, result) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            if (error) {
                // Never propagate URL, header, response content or upstream error messages.
                response?.destroy();
                request?.destroy();
                reject(Object.assign(new Error(error), { code: error }));
            } else resolve(result);
        };
        let url;
        try {
            url = new URL(input);
            if (url.protocol !== 'https:' || url.username || url.password || url.hash ||
                (url.port && url.port !== '443') || !Array.isArray(options.allowedHosts) ||
                !options.allowedHosts.includes(url.hostname) || !Number.isInteger(budget) || budget < 1 ||
                !Number.isInteger(maximum) || maximum < 1 || maximum > 4 * 1024 * 1024) throw new Error();
        } catch { finish('EOS_HTTPS_INVALID_OPTIONS'); return; }
        timer = setTimeout(() => finish('EOS_HTTPS_DEADLINE'), budget);
        // Test transport injection is deliberately absent from this public runtime API.
        try {
            request = https.request(url, {
                method: 'GET', rejectUnauthorized: true, minVersion: 'TLSv1.2', agent: false,
                headers: { Accept: 'application/json', 'Accept-Encoding': 'identity' },
                maxHeaderSize: 16 * 1024,
            }, incoming => {
                response = incoming;
                if (settled) { incoming.destroy(); return; }
                if (incoming.statusCode !== 200) { finish('EOS_HTTPS_STATUS'); return; }
                const encoding = incoming.headers['content-encoding'];
                if (encoding && encoding !== 'identity') { finish('EOS_HTTPS_ENCODING'); return; }
                const length = incoming.headers['content-length'];
                if (length && (!/^\d+$/.test(length) || Number(length) > maximum)) {
                    finish('EOS_HTTPS_TOO_LARGE'); return;
                }
                let bytes = 0;
                const chunks = [];
                incoming.on('data', chunk => {
                    if (settled) return;
                    if (performance.now() - started >= budget) { finish('EOS_HTTPS_DEADLINE'); return; }
                    bytes += chunk.length;
                    if (bytes > maximum) { finish('EOS_HTTPS_TOO_LARGE'); return; }
                    chunks.push(chunk);
                });
                incoming.once('error', () => finish('EOS_HTTPS_RESPONSE'));
                incoming.once('aborted', () => finish('EOS_HTTPS_RESPONSE'));
                incoming.once('end', () => {
                    if (settled) return;
                    try {
                        if (performance.now() - started >= budget) { finish('EOS_HTTPS_DEADLINE'); return; }
                        const value = JSON.parse(Buffer.concat(chunks, bytes).toString('utf8'));
                        if (!value || typeof value !== 'object') { finish('EOS_HTTPS_JSON'); return; }
                        if (performance.now() - started >= budget) { finish('EOS_HTTPS_DEADLINE'); return; }
                        finish(null, value);
                    } catch { finish('EOS_HTTPS_JSON'); }
                });
            });
            request.once('error', () => finish('EOS_HTTPS_REQUEST'));
            request.end();
        } catch { finish('EOS_HTTPS_REQUEST'); }
    });
}
module.exports = { requestHttpsJson };

'use strict';

// Offline license verification and encrypted local storage. No issuer private
// key or shared secret belongs in this module or in the adapter distribution.
const crypto = require('node:crypto');
const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');
const { TextDecoder } = require('node:util');

const MAX_TOKEN_BYTES = 16384;
const MAX_STORE_BYTES = 32768;
const MAX_TIME = 8640000000000000;
const UUID_RE = /^(?:[a-z]{2})?[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const KID_RE = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const ADAPTER_RE = /^[a-z][a-z0-9-]{0,63}$/;
const POSIX = process.platform !== 'win32';
const NOFOLLOW = fs.constants.O_NOFOLLOW || 0;
const OWN_UID = typeof process.getuid === 'function' ? process.getuid() : null;

class LicenseError extends Error {
    constructor(code) {
        // Deliberately avoid token, plaintext, path and cryptographic details.
        super(code);
        this.name = 'LicenseError';
        this.code = code;
    }
}

function fail(code) {
    throw new LicenseError(code);
}

function plain(value) {
    return !!value && typeof value === 'object' && !Array.isArray(value) &&
        (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
}

function exactKeys(value, keys) {
    return plain(value) && Object.keys(value).length === keys.length &&
        keys.every(key => Object.prototype.hasOwnProperty.call(value, key));
}

function validTime(value) {
    return Number.isSafeInteger(value) && value >= 0 && value <= MAX_TIME;
}

function normalizeUuid(uuid) {
    if (typeof uuid !== 'string' || uuid.length > 128) fail('LICENSE_UUID_INVALID');
    const normalized = uuid.trim().toLowerCase();
    if (!UUID_RE.test(normalized)) fail('LICENSE_UUID_INVALID');
    return normalized;
}

function decode64(value, code, maxBytes) {
    if (typeof value !== 'string' || !value || value.length > Math.ceil(maxBytes * 4 / 3) ||
        !/^[A-Za-z0-9_-]+$/.test(value)) fail(code);
    const decoded = Buffer.from(value, 'base64url');
    if (decoded.length > maxBytes || decoded.toString('base64url') !== value) fail(code);
    return decoded;
}

function parseJson(buffer, code) {
    try {
        // JSON.parse alone replaces malformed UTF-8 and is insufficient here.
        return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(buffer));
    } catch (_) {
        fail(code);
    }
}

function validatePublicKeys(publicKeys) {
    if (!plain(publicKeys)) fail('TRUST_INVALID');
    const entries = Object.entries(publicKeys);
    if (entries.length < 1 || entries.length > 32) fail('TRUST_INVALID');
    const result = Object.create(null);
    for (const [kid, pem] of entries) {
        if (!KID_RE.test(kid) || typeof pem !== 'string' || pem.length > 1024 ||
            !/^-----BEGIN PUBLIC KEY-----\r?\n[A-Za-z0-9+/=\r\n]+\r?\n-----END PUBLIC KEY-----\s*$/.test(pem)) {
            fail('TRUST_INVALID');
        }
        try {
            const key = crypto.createPublicKey(pem);
            if (key.type !== 'public' || key.asymmetricKeyType !== 'ed25519') fail('TRUST_INVALID');
            result[kid] = key.export({ format: 'pem', type: 'spki' }).toString();
        } catch (_) {
            fail('TRUST_INVALID');
        }
    }
    return Object.freeze(result);
}

function verifyLicense(token, options = {}) {
    if (!plain(options)) fail('LICENSE_OPTIONS_INVALID');
    const uuid = normalizeUuid(options.uuid);
    const now = options.now === undefined ? Date.now() : options.now;
    if (!validTime(now)) fail('LICENSE_TIME_INVALID');
    if (typeof token !== 'string' || token.length > MAX_TOKEN_BYTES || !token.startsWith('NWL2.')) {
        fail('LICENSE_FORMAT_INVALID');
    }
    const parts = token.split('.');
    if (parts.length !== 3 || parts[0] !== 'NWL2') fail('LICENSE_FORMAT_INVALID');
    const payloadBytes = decode64(parts[1], 'LICENSE_FORMAT_INVALID', 10000);
    const signature = decode64(parts[2], 'LICENSE_FORMAT_INVALID', 64);
    if (signature.length !== 64) fail('LICENSE_FORMAT_INVALID');
    const payload = parseJson(payloadBytes, 'LICENSE_FORMAT_INVALID');
    if (!plain(payload) || typeof payload.kid !== 'string' || !KID_RE.test(payload.kid)) {
        fail('LICENSE_CLAIMS_INVALID');
    }
    const publicKeys = validatePublicKeys(options.publicKeys);
    if (!Object.prototype.hasOwnProperty.call(publicKeys, payload.kid)) fail('LICENSE_KEY_UNKNOWN');
    let authentic = false;
    try {
        authentic = crypto.verify(null, Buffer.from(`NWL2.${parts[1]}`, 'ascii'), publicKeys[payload.kid], signature);
    } catch (_) {
        fail('LICENSE_SIGNATURE_INVALID');
    }
    if (!authentic) fail('LICENSE_SIGNATURE_INVALID');
    if (!exactKeys(payload, ['v', 'kid', 'licenseId', 'uuid', 'edition', 'issuedAt', 'notBefore', 'expiresAt', 'adapters', 'limits']) ||
        payload.v !== 2 || typeof payload.licenseId !== 'string' ||
        !/^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/.test(payload.licenseId) ||
        !['home', 'pro'].includes(payload.edition) || !validTime(payload.issuedAt) ||
        !validTime(payload.notBefore) || payload.notBefore < payload.issuedAt ||
        !(payload.expiresAt === null || (validTime(payload.expiresAt) && payload.expiresAt > payload.notBefore)) ||
        !Array.isArray(payload.adapters) || payload.adapters.length < 1 || payload.adapters.length > 64 ||
        !payload.adapters.every(name => typeof name === 'string' && ADAPTER_RE.test(name)) ||
        new Set(payload.adapters).size !== payload.adapters.length ||
        !exactKeys(payload.limits, ['chargePoints', 'batteries']) ||
        !Number.isSafeInteger(payload.limits.chargePoints) || payload.limits.chargePoints < 1 ||
        payload.limits.chargePoints > (payload.edition === 'home' ? 3 : 1000) ||
        !Number.isSafeInteger(payload.limits.batteries) || payload.limits.batteries < 0 ||
        payload.limits.batteries > (payload.edition === 'home' ? 2 : 10)) {
        fail('LICENSE_CLAIMS_INVALID');
    }
    if (normalizeUuid(payload.uuid) !== uuid) fail('LICENSE_UUID_MISMATCH');
    if (now < payload.notBefore || now < payload.issuedAt) fail('LICENSE_NOT_YET_VALID');
    if (payload.expiresAt !== null && now >= payload.expiresAt) fail('LICENSE_EXPIRED');
    const features = ['energy', 'wallet', 'smartHome', 'microgridSlave'];
    if (payload.edition === 'pro') features.push('microgridMaster', 'multisite', 'billing');
    // A fresh immutable result prevents consumer mutation from escalating rights.
    return Object.freeze({
        v: 2,
        kid: payload.kid,
        licenseId: payload.licenseId,
        uuid,
        edition: payload.edition,
        issuedAt: payload.issuedAt,
        notBefore: payload.notBefore,
        expiresAt: payload.expiresAt,
        adapters: Object.freeze([...payload.adapters]),
        limits: Object.freeze({ ...payload.limits }),
        features: Object.freeze(features),
    });
}

function protectedStat(stat, directory = false) {
    if ((directory ? !stat.isDirectory() : !stat.isFile()) ||
        (POSIX && (stat.uid !== OWN_UID || (stat.mode & 0o077) !== 0)) ||
        (!directory && stat.nlink !== 1)) fail('STORAGE_UNSAFE_PATH');
}

async function statIfExists(filename) {
    try {
        return await fsp.lstat(filename);
    } catch (error) {
        if (error.code === 'ENOENT') return null;
        throw error;
    }
}

/** AES-256-GCM storage, scoped to one normalized device UUID.
 * POSIX: private directory/files, current owner, no symlinks/hard-linked files.
 * Windows additionally requires an installer-provisioned private account ACL.
 * Same-UID/root attackers and full-disk rollback require an external trust root.
 */
class EncryptedLicenseStore {
    constructor({ directory, uuid } = {}) {
        if (typeof directory !== 'string' || !path.isAbsolute(directory) || directory.includes('\0')) {
            fail('STORAGE_DIRECTORY_INVALID');
        }
        this.directory = path.resolve(directory);
        if (this.directory === path.parse(this.directory).root) fail('STORAGE_DIRECTORY_INVALID');
        this.uuid = normalizeUuid(uuid);
        this.keyPath = path.join(this.directory, 'storage.key');
        this.licensePath = path.join(this.directory, 'license.enc');
        this.aad = Buffer.from(JSON.stringify(['NexoWatt EOS license store', 1, this.uuid]), 'utf8');
        this._tail = Promise.resolve();
    }

    _run(operation) {
        const result = this._tail.then(async () => {
            try {
                await this._prepareDirectory();
                return await operation();
            } catch (error) {
                if (error instanceof LicenseError) throw error;
                fail('STORAGE_IO_ERROR');
            }
        });
        this._tail = result.catch(() => {});
        return result;
    }

    async _prepareDirectory() {
        // Walk before creating: recursive mkdir otherwise follows existing links.
        const parsed = path.parse(this.directory);
        let current = parsed.root;
        const segments = this.directory.slice(parsed.root.length).split(path.sep).filter(Boolean);
        for (let index = 0; index < segments.length; index++) {
            current = path.join(current, segments[index]);
            let stat = await statIfExists(current);
            if (!stat) {
                try {
                    await fsp.mkdir(current, { mode: 0o700 });
                } catch (error) {
                    if (error.code !== 'EEXIST') throw error;
                }
                stat = await fsp.lstat(current);
            }
            if (!stat.isDirectory() || stat.isSymbolicLink()) fail('STORAGE_UNSAFE_PATH');
            if (POSIX && stat.uid !== OWN_UID && stat.uid !== 0) fail('STORAGE_UNSAFE_PATH');
            // Shared temporary roots are allowed only with the sticky bit. The
            // private final directory must still be owned by this service UID.
            if (POSIX && (stat.mode & 0o022) && !(stat.mode & 0o1000)) fail('STORAGE_UNSAFE_PATH');
            if (index === segments.length - 1) protectedStat(stat, true);
        }
    }

    async _read(filename, maxBytes) {
        const before = await statIfExists(filename);
        if (!before) return null;
        protectedStat(before);
        let handle;
        try {
            handle = await fsp.open(filename, fs.constants.O_RDONLY | NOFOLLOW);
            const stat = await handle.stat();
            protectedStat(stat);
            if (before.dev !== stat.dev || before.ino !== stat.ino) fail('STORAGE_UNSAFE_PATH');
            if (stat.size > maxBytes) fail('STORAGE_SIZE_INVALID');
            const buffer = Buffer.alloc(maxBytes + 1);
            let total = 0;
            while (total < buffer.length) {
                const { bytesRead } = await handle.read(buffer, total, buffer.length - total, null);
                if (bytesRead === 0) break;
                total += bytesRead;
            }
            if (total > maxBytes) fail('STORAGE_SIZE_INVALID');
            return buffer.subarray(0, total);
        } finally {
            if (handle) await handle.close();
        }
    }

    async _key(create, hasLicense) {
        let key = await this._read(this.keyPath, 32);
        if (!key && hasLicense) fail('STORAGE_KEY_MISSING');
        if (!key && create) {
            const candidate = crypto.randomBytes(32);
            let handle;
            try {
                handle = await fsp.open(this.keyPath, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | NOFOLLOW, 0o600);
                await handle.writeFile(candidate);
                await handle.sync();
            } catch (error) {
                if (error.code !== 'EEXIST') throw error;
            } finally {
                candidate.fill(0);
                if (handle) await handle.close();
            }
            key = await this._read(this.keyPath, 32);
        }
        if (key && key.length !== 32) fail('STORAGE_KEY_INVALID');
        return key;
    }

    _decode(encrypted, key) {
        const envelope = parseJson(encrypted, 'STORAGE_FORMAT_INVALID');
        if (!exactKeys(envelope, ['v', 'alg', 'iv', 'ciphertext', 'tag']) || envelope.v !== 1 || envelope.alg !== 'A256GCM') {
            fail('STORAGE_FORMAT_INVALID');
        }
        const iv = decode64(envelope.iv, 'STORAGE_FORMAT_INVALID', 12);
        const tag = decode64(envelope.tag, 'STORAGE_FORMAT_INVALID', 16);
        const ciphertext = decode64(envelope.ciphertext, 'STORAGE_FORMAT_INVALID', 20000);
        if (iv.length !== 12 || tag.length !== 16) fail('STORAGE_FORMAT_INVALID');
        let plaintext;
        try {
            const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv, { authTagLength: 16 });
            decipher.setAAD(this.aad);
            decipher.setAuthTag(tag);
            plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
        } catch (_) {
            fail('STORAGE_AUTH_FAILED');
        }
        try {
            const data = parseJson(plaintext, 'STORAGE_FORMAT_INVALID');
            this._validateData(data);
            return data;
        } finally {
            plaintext.fill(0);
        }
    }

    _validateData(data) {
        if (!exactKeys(data, ['token', 'highWaterMark']) || typeof data.token !== 'string' ||
            !data.token.startsWith('NWL2.') || data.token.length > MAX_TOKEN_BYTES ||
            !validTime(data.highWaterMark)) fail('STORAGE_DATA_INVALID');
    }

    async _syncDirectory() {
        // Directory fsync is a POSIX durability primitive, unavailable on Windows.
        if (!POSIX) return;
        const handle = await fsp.open(this.directory, fs.constants.O_RDONLY | NOFOLLOW);
        try {
            protectedStat(await handle.stat(), true);
            await handle.sync();
        } finally {
            await handle.close();
        }
    }

    async _atomicWrite(content) {
        const temporary = path.join(this.directory, `.license-${crypto.randomBytes(12).toString('hex')}.tmp`);
        let handle;
        try {
            handle = await fsp.open(temporary, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | NOFOLLOW, 0o600);
            await handle.writeFile(content);
            await handle.sync();
            await handle.close();
            handle = null;
            const existing = await statIfExists(this.licensePath);
            if (existing) protectedStat(existing);
            await fsp.rename(temporary, this.licensePath);
            await this._syncDirectory();
        } finally {
            if (handle) await handle.close();
            try {
                await fsp.unlink(temporary);
            } catch (error) {
                if (error.code !== 'ENOENT') throw error;
            }
        }
    }

    async load() {
        return this._run(async () => {
            const encrypted = await this._read(this.licensePath, MAX_STORE_BYTES);
            if (!encrypted) return null;
            const key = await this._key(false, true);
            try {
                return this._decode(encrypted, key);
            } finally {
                key.fill(0);
            }
        });
    }

    async save(data) {
        // Snapshot inputs now so callers cannot mutate queued writes.
        this._validateData(data);
        const snapshot = { token: data.token, highWaterMark: data.highWaterMark };
        return this._run(async () => {
            const existing = await this._read(this.licensePath, MAX_STORE_BYTES);
            const key = await this._key(true, existing !== null);
            let plaintext;
            try {
                if (existing && this._decode(existing, key).highWaterMark > snapshot.highWaterMark) {
                    fail('STORAGE_CLOCK_ROLLBACK');
                }
                const iv = crypto.randomBytes(12);
                const cipher = crypto.createCipheriv('aes-256-gcm', key, iv, { authTagLength: 16 });
                cipher.setAAD(this.aad);
                plaintext = Buffer.from(JSON.stringify(snapshot), 'utf8');
                const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
                const envelope = JSON.stringify({
                    v: 1,
                    alg: 'A256GCM',
                    iv: iv.toString('base64url'),
                    ciphertext: ciphertext.toString('base64url'),
                    tag: cipher.getAuthTag().toString('base64url'),
                });
                await this._atomicWrite(envelope);
            } finally {
                key.fill(0);
                if (plaintext) plaintext.fill(0);
            }
        });
    }

    async clear() {
        return this._run(async () => {
            const stat = await statIfExists(this.licensePath);
            if (!stat) return;
            protectedStat(stat);
            await fsp.unlink(this.licensePath);
            await this._syncDirectory();
        });
    }
}

module.exports = { LicenseError, normalizeUuid, validatePublicKeys, verifyLicense, EncryptedLicenseStore };

'use strict';

const { safeCode } = require('./eosLicenseService');

function isLocal(address) {
    return address === '127.0.0.1' || address === '::1' || address === '::ffff:127.0.0.1';
}

function sameOrigin(req, secure) {
    // Neither forwarded-host nor forwarded-proto is a trust source here.
    try {
        const origin = new URL(req.headers.origin);
        return origin.origin === `${secure ? 'https' : 'http'}://${req.headers.host}`
            && req.headers['x-eos-license'] === '1'
            && (!req.headers['sec-fetch-site'] || req.headers['sec-fetch-site'] === 'same-origin');
    } catch { return false; }
}

function registerLicenseRoutes(app, { service, authorize, secure, jsonParser, pagePath, scriptPath }) {
    const rates = new Map();
    const guard = (write = false) => async (req, res, next) => {
        res.setHeader('Cache-Control', 'no-store');
        res.setHeader('Pragma', 'no-cache');
        res.setHeader('X-Content-Type-Options', 'nosniff');
        try {
            if (!await authorize(req)) return res.status(403).json({ error: 'LICENSE_ADMIN_REQUIRED' });
            // UUIDs and activation tokens must not travel over plaintext LAN.
            if (!secure && !isLocal(req.socket?.remoteAddress)) return res.status(403).json({ error: 'LICENSE_HTTPS_REQUIRED' });
            if (write && !sameOrigin(req, secure)) return res.status(403).json({ error: 'LICENSE_ORIGIN' });
            const now = Date.now();
            for (const [key, value] of rates) if (now - value.start >= 60000) rates.delete(key);
            const key = `${write ? 'w' : 'r'}:${req.socket?.remoteAddress || 'unknown'}`;
            let rate = rates.get(key);
            if (!rate) {
                if (rates.size >= 128) return res.status(429).json({ error: 'LICENSE_RATE_LIMIT' });
                rate = { start: now, count: 0 };
                rates.set(key, rate);
            }
            if (++rate.count > (write ? 10 : 60)) return res.status(429).json({ error: 'LICENSE_RATE_LIMIT' });
            next();
        } catch { res.status(503).json({ error: 'SERVICE_UNAVAILABLE' }); }
    };
    const handle = operation => (req, res) => {
        void Promise.resolve().then(() => operation(req)).then(result => res.status(200).json(result)).catch(error => {
            res.status(400).json({ error: safeCode(error) });
        });
    };
    app.get('/nexowatt/license', guard(), (_req, res) => {
        res.setHeader('Content-Security-Policy', "default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'self'; form-action 'self'");
        res.sendFile(pagePath);
    });
    app.get('/nexowatt/license/app.js', guard(), (_req, res) => res.sendFile(scriptPath));
    app.get('/nexowatt/license/status', guard(), handle(() => service.status()));
    app.post('/nexowatt/license/activate', guard(true), jsonParser, handle(req => {
        if (!req.body || Array.isArray(req.body) || Object.keys(req.body).length !== 1 || typeof req.body.token !== 'string' || req.body.token.length > 16384) {
            throw Object.assign(new Error('LICENSE_FORMAT'), { code: 'LICENSE_FORMAT' });
        }
        return service.activate(req.body.token.trim());
    }));
    app.post('/nexowatt/license/remove', guard(true), jsonParser, handle(req => {
        if (!req.body || Array.isArray(req.body) || Object.keys(req.body).length !== 0) throw Object.assign(new Error('LICENSE_FORMAT'), { code: 'LICENSE_FORMAT' });
        return service.remove();
    }));
    // Body parser errors must never serialize input or stack traces.
    app.use('/nexowatt/license', (error, _req, res, _next) => {
        res.status(error?.type === 'entity.too.large' ? 413 : 400).json({ error: 'LICENSE_REQUEST' });
    });
}

module.exports = { registerLicenseRoutes, sameOrigin, isLocal };

