    let bytes = 0;
    return new Transform({ transform(chunk: Buffer, _encoding, callback) {
        bytes += chunk.length;
        callback(bytes > limit ? new Error('EOS_PROXY_SIZE_LIMIT') : null, bytes > limit ? undefined : chunk);
    } });
}
function connectionHeaders(headers: IncomingHttpHeaders): Set<string> {
    const denied = new Set(HOP_HEADERS);
    if (typeof headers.connection === 'string') for (const field of headers.connection.split(',')) denied.add(field.trim().toLowerCase());
    return denied;
}
function rejectUpgrade(socket: Duplex, status: number): void {
    const labels: Record<number, string> = { 400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 429: 'Too Many Requests', 502: 'Bad Gateway', 503: 'Service Unavailable' };
    if (socket.writable && !socket.destroyed) socket.end(`HTTP/1.1 ${status} ${labels[status] || 'Bad Gateway'}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`);
    else socket.destroy();
}

export class InstanceProxy {
    private readonly adapter: ProxyAdapter;
    private readonly publicPath: string;
    private readonly active = new Set<Active>();
    private databasePending = 0;
    private stopped = false;
    private generation = 0;
    private detach: (() => void) | undefined;

    constructor(adapter: ProxyAdapter, publicPath: string) {
        const parts = publicPath.slice(1, -1).split('/');
        if (publicPath.length > 256 || !publicPath.startsWith('/') || !publicPath.endsWith('/') ||
            (publicPath !== '/' && parts.some(part => !/^[A-Za-z0-9._~-]{1,128}$/.test(part) || part === '.' || part === '..' || part === 'proxy'))) {
            throw new Error('EOS_PROXY_PUBLIC_PATH_INVALID');
        }
        this.adapter = adapter;
        this.publicPath = publicPath;
    }

    private relative(url: string | undefined): string | null {
        if (!url || url.length > 8192) return null;
        return this.publicPath !== '/' && url.startsWith(this.publicPath) ? url.slice(this.publicPath.length - 1) : url;
    }
    matches(url: string | undefined): boolean {
        const relative = this.relative(url);
        return relative !== null && (relative === '/proxy' || relative.startsWith('/proxy/'));
    }
    private parse(url: string | undefined): Parsed | null {
        const relative = this.relative(url);
        if (!relative || /[\\\x00-\x20\x7f#]/.test(relative)) return null;
        const match = /^\/proxy\/([a-z0-9][a-z0-9_-]{0,127}\.(?:0|[1-9]\d{0,5}))(\/[^?]*)?(\?.*)?$/.exec(relative);
        if (!match?.[1]) return null;
        const path = match[2] || null;
        if (path) {
            if (path.includes('//') || /%(?:2f|5c|25|0[0-9a-f]|1[0-9a-f]|7f)/i.test(path)) return null;
            try {
                const decoded = decodeURIComponent(path);
                if (decoded.split('/').some(part => part === '.' || part === '..')) return null;
            } catch { return null; }
        }
        const query = match[3] || '';
        if (query.length > 4096) return null;
        const search = new URLSearchParams(query);
        if (['access_token', 'refresh_token', 'password', 'pass'].some(key => search.has(key))) return null;
        return { instance: match[1], path, query };
    }
    private prefix(instance: string): string { return `${this.publicPath}proxy/${instance}`; }

    private lookup<T>(operation: () => Promise<T>): Promise<T> {
        if (this.stopped || this.databasePending >= MAX_DATABASE_PENDING) return Promise.reject(new Error('EOS_PROXY_LOOKUP_BUSY'));
        this.databasePending++;
        const work = Promise.resolve().then(operation).finally(() => { this.databasePending--; });
        // An unresponsive database still occupies its slot after the caller times
        // out, preventing repeated requests from accumulating pending work.
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => reject(new Error('EOS_PROXY_LOOKUP_TIMEOUT')), LOOKUP_MS);
            work.then(value => { clearTimeout(timer); resolve(value); }, error => { clearTimeout(timer); reject(error); });
        });
    }
    private async getUser(headers: IncomingHttpHeaders): Promise<string | null> {
        if (this.adapter.config.auth !== true) return null;
        const access = token(headers);
        if (!access) return null;
        const raw = await this.lookup(() => new Promise<unknown>(resolve => { this.adapter.getSession(`a:${access}`, resolve); }));
        const session = object(raw);
        if (!session || session.aud || session.clientId || typeof session.aExp !== 'number' || !Number.isFinite(session.aExp) || session.aExp <= Date.now()) return null;
        const user = userId(session.user);
        if (!user) return null;
        const account = object(await this.lookup(() => this.adapter.getForeignObjectAsync(user)));
        const common = object(account?.common);
        const native = object(account?.native);
        const accountMeta = object(native?.nexowattEosAccount);
        if (account?.type !== 'user' || !common || common.enabled === false || accountMeta?.forcePasswordChange === true ||
            native?.nexowattPasswordChangeRequired === true || native?.eosPasswordChangeRequired === true ||
            native?.nexowattFirstLoginPending === true || native?.eosFirstLoginRequired === true) return null;
        return user;
    }
    private async isAdministrator(user: string): Promise<boolean> {
        const group = object(await this.lookup(() => this.adapter.getForeignObjectAsync('system.group.administrator')));
        const members = object(group?.common)?.members;
        return group?.type === 'group' && Array.isArray(members) && members.length <= 4096 && members.includes(user);
    }
    private async getHostAddress(hostname: string): Promise<string | null> {
        const hostObject = object(await this.lookup(() => this.adapter.getForeignObjectAsync(`system.host.${hostname}`)));
        const hardware = object(object(hostObject?.native)?.hardware);
        const interfaces = object(hardware?.networkInterfaces);
        if (interfaces && Object.keys(interfaces).length <= 128) for (const values of Object.values(interfaces)) {
            if (!Array.isArray(values) || values.length > 64) continue;
            for (const raw of values) {
                const item = object(raw);
                if (item?.internal === false && item.family === 'IPv4' && typeof item.address === 'string' && isIP(item.address) === 4 && !loopback(item.address)) return item.address;
            }
        }
        const addresses = object(hostObject?.common)?.address;
        if (Array.isArray(addresses)) for (const value of addresses.slice(0, 64)) {
            const host = checkedHost(value);
            if (host && !loopback(host)) return host;
        }
        return null;
    }
    private async getTarget(instance: string): Promise<Target | null> {
        if (instance === this.adapter.namespace) return null;
        const value = object(await this.lookup(() => this.adapter.getForeignObjectAsync(`system.adapter.${instance}`)));
        const common = object(value?.common);
        const native = object(value?.native);
        if (value?.type !== 'instance' || !common || !native || common.enabled === false || object(common.adminTab)?.proxy !== true) return null;
        const rawPort = native.port;
        const port = typeof rawPort === 'number' ? rawPort : typeof rawPort === 'string' && /^\d{1,5}$/.test(rawPort) ? Number(rawPort) : 0;
        if (!Number.isInteger(port) || port < 1 || port > 65535 || (native.secure !== undefined && typeof native.secure !== 'boolean')) return null;
        if (typeof common.host !== 'string' || !/^[A-Za-z0-9_.-]{1,253}$/.test(common.host)) return null;
        if (!this.adapter.host || !/^[A-Za-z0-9_.-]{1,253}$/.test(this.adapter.host)) return null;
        const sameHost = common.host === this.adapter.host;
        const bind = native.bind;
        let host: string | null;
        if (bind === undefined || bind === '' || bind === '0.0.0.0' || bind === '::') host = sameHost ? '127.0.0.1' : await this.getHostAddress(common.host);
