        if (!user) { deny(401); return null; }
        if (!(await this.isAdministrator(user))) { deny(403); return null; }
        const target = await this.getTarget(instance);
        if (!target) { deny(404); return null; }
        if (this.stopped || this.generation !== generation) { deny(401); return null; }
        return { user, target };
    }
    private sameOrigin(req: IncomingMessage, upgrade = false): boolean {
