            if (value === undefined || denied.has(name) || name === 'service-worker-allowed' || name === 'clear-site-data') continue;
            if (name === 'set-cookie') {
                const cookies = (Array.isArray(value) ? value : [value]).slice(0, 64).map(cookie => this.rewriteCookie(cookie, prefix)).filter((cookie): cookie is string => cookie !== null);
                if (cookies.length) headers[name] = cookies;
            } else if (name === 'location' && typeof value === 'string') {
                if (value.startsWith('/') && !value.startsWith('//')) headers[name] = value === prefix || value.startsWith(`${prefix}/`) ? value : `${prefix}${value}`;
                else {
                    try {
                        const url = new URL(value);
                        headers[name] = (url.hostname === target.host && Number(url.port || (url.protocol === 'https:' ? 443 : 80)) === target.port) || url.host === host
                            ? `${prefix}${url.pathname}${url.search}${url.hash}` : value;
                    } catch { headers[name] = value; }
                }
            } else headers[name] = value;
        }
        return headers;
    }
    hideAuthorization = (req: Request, _res: Response, next: NextFunction): void => {
        if (req.headers.authorization && this.matches(req.url)) {
            (req as Request & { [HIDDEN_AUTHORIZATION]?: string })[HIDDEN_AUTHORIZATION] = req.headers.authorization;
            delete req.headers.authorization;
        }
        next();
    };

    handleRequest = (req: Request, res: Response, next: NextFunction): void => {
        if (!this.matches(req.url)) { next(); return; }
        const parsed = this.parse(req.url);
        if (!parsed) { res.status(400).send('Invalid proxy path'); return; }
        if (!this.sameOrigin(req)) { res.status(403).send('Forbidden'); return; }
        if (this.stopped || this.active.size >= MAX_ACTIVE) { res.status(503).send('Proxy capacity unavailable'); return; }
        const prefix = this.prefix(parsed.instance);
        let cancelled = false;
        let proxyReq: ClientRequest | undefined;
        let proxyRes: IncomingMessage | undefined;
        let body: Transform | undefined;
        let output: Transform | undefined;
        let timer: ReturnType<typeof setTimeout> | undefined;
        let recheck: ReturnType<typeof setInterval> | undefined;
        const cleanup = (): void => {
            cancelled = true;
            clearTimeout(timer); clearInterval(recheck);
            this.active.delete(record);
            req.unpipe(); body?.destroy(); output?.destroy(); proxyReq?.destroy(); proxyRes?.destroy();
        };
        const record: Active = { close: () => { cleanup(); res.destroy(); } };
        const deny = (status: number): void => {
            if (!cancelled && !res.headersSent) res.status(status).send(status === 401 ? 'Unauthorized' : 'Proxy request refused');
            else if (!cancelled) res.destroy();
            cleanup();
        };
        this.active.add(record);
        timer = setTimeout(() => deny(504), HTTP_MS);
        res.once('close', cleanup);
        req.once('aborted', () => deny(400));
        void this.authorize(req.headers, parsed.instance, deny).then(auth => {
            if (!auth || cancelled) return;
            if (!parsed.path) { res.redirect(301, `${prefix}/${parsed.query}`); cleanup(); return; }
            const target = auth.target;
            proxyReq = (target.protocol === 'https:' ? https : http).request({
                protocol: target.protocol, host: target.host, port: target.port, method: req.method,
                path: `${parsed.path}${parsed.query}`, headers: this.requestHeaders(req, prefix),
                rejectUnauthorized: true, minVersion: 'TLSv1.2', agent: false,
            });
            proxyReq.on('error', () => deny(502));
            proxyReq.on('response', incoming => {
                if (cancelled) { incoming.destroy(); return; }
                proxyRes = incoming;
                if (incoming.headers['content-type']?.split(';', 1)[0]?.trim().toLowerCase() === 'text/event-stream') {
                    clearTimeout(timer);
                    timer = setTimeout(() => record.close(), STREAM_MS);
                    incoming.setTimeout(STREAM_IDLE_MS, () => record.close());
                    let checking = false;
                    recheck = setInterval(() => {
                        if (checking || cancelled) return;
                        checking = true;
                        void this.authorize(req.headers, parsed.instance, () => record.close()).then(current => {
                            if (!current || current.user !== auth.user || JSON.stringify(current.target) !== JSON.stringify(target)) record.close();
                        }).catch(() => record.close()).finally(() => { checking = false; });
                    }, AUTH_RECHECK_MS);
                    recheck.unref();
                }
                res.writeHead(incoming.statusCode || 502, this.responseHeaders(incoming.headers, prefix, target, req.headers.host || ''));
                output = limitedStream(RESPONSE_BYTES);
                output.on('error', () => record.close());
                incoming.on('error', () => record.close());
                incoming.pipe(output).pipe(res);
            });
            body = limitedStream(REQUEST_BYTES);
            body.on('error', () => deny(413));
            req.pipe(body).pipe(proxyReq);
        }).catch(() => deny(503));
    };

    private handleUpgrade(req: IncomingMessage, socket: Duplex, head: Buffer, parsed: Parsed): void {
        if (!parsed.path || !this.sameOrigin(req, true) || req.headers.upgrade?.toLowerCase() !== 'websocket' || head.length > 65536) { rejectUpgrade(socket, 403); return; }
        if (this.stopped || this.active.size >= MAX_ACTIVE) { rejectUpgrade(socket, 503); return; }
        let cancelled = false;
        let proxyReq: ClientRequest | undefined;
        let upstream: Duplex | undefined;
        let recheck: ReturnType<typeof setInterval> | undefined;
        let timer: ReturnType<typeof setTimeout> | undefined;
        const shutdown = (preserveClient: boolean): void => {
            cancelled = true;
            clearTimeout(timer); clearInterval(recheck);
            this.active.delete(record);
            proxyReq?.destroy(); upstream?.destroy();
            if (!preserveClient) socket.destroy();
        };
        const close = (): void => shutdown(false);
        const reject = (status: number): void => { shutdown(true); rejectUpgrade(socket, status); };
        const record: Active = { close };
        this.active.add(record);
        socket.on('error', close);
        socket.once('close', close);
        timer = setTimeout(close, HTTP_MS);
        void this.authorize(req.headers, parsed.instance, reject).then(auth => {
            if (!auth || cancelled) { if (!cancelled) close(); return; }
            const target = auth.target;
            const headers = this.requestHeaders(req, this.prefix(parsed.instance));
            headers.connection = 'Upgrade'; headers.upgrade = 'websocket';
            proxyReq = (target.protocol === 'https:' ? https : http).request({
                protocol: target.protocol, host: target.host, port: target.port, method: 'GET',
                path: `${parsed.path}${parsed.query}`, headers, rejectUnauthorized: true, minVersion: 'TLSv1.2', agent: false,
            });
            proxyReq.on('error', () => { if (!cancelled) reject(502); });
            proxyReq.on('response', response => { response.destroy(); reject(response.statusCode || 502); });
            proxyReq.on('upgrade', (response, remote, first) => {
                if (cancelled) { remote.destroy(); return; }
                upstream = remote;
                clearTimeout(timer); timer = setTimeout(close, STREAM_MS);
                if (remote instanceof Socket) remote.setTimeout(STREAM_IDLE_MS, close);
                let checking = false;
                recheck = setInterval(() => {
                    if (checking || cancelled) return;
                    checking = true;
                    void this.authorize(req.headers, parsed.instance, close).then(current => {
                        if (!current || current.user !== auth.user || JSON.stringify(current.target) !== JSON.stringify(target)) close();
                    }).catch(close).finally(() => { checking = false; });
                }, AUTH_RECHECK_MS);
                recheck.unref();
                const outgoing = this.responseHeaders(response.headers, this.prefix(parsed.instance), target, req.headers.host || '');
                outgoing.connection = 'Upgrade'; outgoing.upgrade = 'websocket';
                const lines = ['HTTP/1.1 101 Switching Protocols'];
                for (const [name, values] of Object.entries(outgoing)) for (const value of Array.isArray(values) ? values : [values]) {
                    if (value !== undefined) lines.push(`${name}: ${value}`);
                }
                socket.write(`${lines.join('\r\n')}\r\n\r\n`);
                if (first.length) socket.write(first);
                if (head.length) remote.write(head);
                const toTarget = limitedStream(RESPONSE_BYTES), toBrowser = limitedStream(RESPONSE_BYTES);
                toTarget.on('error', close); toBrowser.on('error', close);
                remote.on('error', close); remote.once('close', close);
                socket.pipe(toTarget).pipe(remote).pipe(toBrowser).pipe(socket);
            });
            proxyReq.end();
        }).catch(() => { if (!cancelled) reject(503); });
    }

    /** Intercept proxy upgrades before Admin's pathless websocket server. */
    attach(server: Server): void {
        if (this.detach) return;
        const original = server.emit;
        const proxy = this;
        function emit(this: Server, event: string | symbol, ...args: unknown[]): boolean {
            if (event === 'upgrade') {
                const request = args[0], socket = args[1], head = args[2];
                if (request instanceof http.IncomingMessage && proxy.matches(request.url)) {
                    if (socket instanceof Duplex && Buffer.isBuffer(head)) {
                        const parsed = proxy.parse(request.url);
                        if (parsed) proxy.handleUpgrade(request, socket, head, parsed); else rejectUpgrade(socket, 400);
                    }
                    return true;
                }
            }
            return Boolean(Reflect.apply(original, this, [event, ...args]));
        }
        const fallback = (_req: IncomingMessage, socket: Duplex): void => { if (server.listenerCount('upgrade') === 1) socket.destroy(); };
        server.emit = emit;
        server.on('upgrade', fallback);
        this.detach = () => { if (server.emit === emit) server.emit = original; server.off('upgrade', fallback); };
    }
    /** Called on security-object changes; no cached identity survives a change. */
    invalidate(): void {
        this.generation++;
        for (const item of [...this.active]) item.close();
    }
    close(): void { this.stopped = true; this.invalidate(); this.detach?.(); this.detach = undefined; }
}
